gin(), mem_q.begin() + (long)sel,\n                                mem_q.begin() + (long)sel + 1);\n                r_rr_last_id = sel_id;\n            }\n        }\n        MemRead& h = mem_q.front();\n        ddr_setup_port = (h.id >> 4) & 3u;\n        if (memory_r_interleave) {\n            // Interleave mode uses the same per-request acceptance latency as\n            // the existing overlap model; the serial countdown is unchanged\n            // when this flag is 0.\n            if (g_cycle <= h.accepted_cycle + (long)ptw_latency) {\n                ddr_setup_wait = true;\n                return;\n            }\n        } else if (read_latency_overlap && measurement_phase) {\n            // Same isolated-request delay as the old model: AR accepted at\n            // t first returns at t + latency + 1. Queued requests age from\n            // acceptance, allowing their preparation delays to overlap.\n            if (g_cycle <= h.accepted_cycle + (long)ptw_latency) {\n                ddr_setup_wait = true;\n                return;\n            }\n        } else if (h.latency > 0) {\n            --h.latency;\n            ddr_setup_wait = true;\n            return;\n        }"
